from pathlib import Path
p=Path('work/pocket-research/compile.cjs');s=p.read_text(encoding='utf-8');a=s.index('function trainer(');i=s.index(' return null;',a)
s=s[:i]+r'''
 if(text==="Choose 1 of your Basic Pokémon in play. If you have a Stage 2 card in your hand that evolves from that Pokémon, put that card onto the Basic Pokémon to evolve it, skipping the Stage 1. You can't use this card during your first turn or on a Basic Pokémon that was put into play this turn.")return[{kind:'choosePokemon',stage:0,evolveHand:{skip:true},next:[{kind:'chooseEvolution',skip:true}]}];
 if(text==="Choose 1 of your [G] Pokémon in play. Put a random [G] Pokémon from your deck that evolves from that Pokémon onto that Pokémon to evolve it. You can't use this card during your first turn or on a Pokémon that was put into play this turn.")return[{kind:'choosePokemon',type:'G',evolveDeck:{normalTiming:true,type:'G'},next:[{kind:'randomEvolveChosen',type:'G'}]}];
 if(text==='Choose 1 of your [W] Pokémon in play with a maximum HP of 50 or less. Put a random [W] Pokémon from your deck that evolves from that Pokémon onto that Pokémon to evolve it.')return[{kind:'choosePokemon',type:'W',maxHp:50,evolveDeck:{type:'W'},next:[{kind:'randomEvolveChosen',type:'W'}]}];
 if(text==='Choose 1: ① During this turn, attacks used by your Pokémon that evolve from Eevee do +10 damage to your opponent\'s Active Pokémon. ② Heal 20 damage from each of your Pokémon that evolves from Eevee.')return[{kind:'chooseMode',modes:[{label:'Increase attack damage',program:[{kind:'attackBonus',evolvesFrom:'Eevee',amount:10}]},{label:'Heal Eevee evolutions',program:[{kind:'healAll',evolvesFrom:'Eevee',amount:20}]}]}];
 if(text==='Look at a random Supporter card that\'s not Penny from your opponent\'s deck and shuffle it back into their deck. Use the effect of that card as the effect of this card.')return[{kind:'copyTrainer',opponent:true,from:'deck',excludeName:'Penny'}];
 if(text==='Put 2 random Pokémon from your deck into your hand. For each Pokémon you put into your hand in this way, choose a Pokémon to shuffle from your hand into your deck.')return[{kind:'searchExchange',amount:2}];
 if((m=text.match(/^Put your (Muk or Weezing|Mew ex) in the Active Spot into your hand\.$/)))return[{kind:'require',predicate:{test:'activeNames',names:m[1].split(' or ')}},{kind:'choosePokemon',active:true,returnable:true,next:[{kind:'bounce',destination:'hand'}]}];
 if((m=text.match(/^Put 1 of your \[([A-Z])\] Pokémon (that has damage on it|in play, except any Pokémon ex), into your hand\.$/)))return[{kind:'choosePokemon',type:m[1],wounded:m[2].startsWith('that'),notEx:m[2].includes('except'),returnable:true,next:[{kind:'bounce',destination:'hand'}]}];
 if(text==='Put 1 of your [C] Pokémon that has damage on it into your hand.')return[{kind:'choosePokemon',type:'C',wounded:true,returnable:true,next:[{kind:'bounce',destination:'hand'}]}];
 if(text==='Put 1 of your [W] Pokémon in play, except any Pokémon ex, into your hand.')return[{kind:'choosePokemon',type:'W',notEx:true,returnable:true,next:[{kind:'bounce',destination:'hand'}]}];
 if(text==='Shuffle 1 of your Future Pokémon in play into your deck.')return[{kind:'choosePokemon',tag:'future',returnable:true,next:[{kind:'bounce',destination:'deck'}]}];
 if(text==='Discard a Pokémon Tool card from a Pokémon (yours or your opponent\'s) , or discard a Stadium card in play.')return[{kind:'chooseRemoval'}];
 if(text==='Switch in 1 of your opponent\'s Benched Pokémon to the Active Spot.')return[{kind:'choosePokemon',side:'opponent',bench:true,next:[{kind:'switch'}]}];
 if(text==='Discard 2 random Energy from your opponent\'s Active Pokémon.')return[{kind:'randomEnergyDiscard',opponent:true,amount:2}];
 if(text==='During this turn, attacks used by your Magneton or Heliolisk do +20 damage to your opponent\'s Pokémon.')return[{kind:'attackBonus',names:['Magneton','Heliolisk'],amount:20,benchAlso:true}];
 if(text==='Look at the top 3 cards of your deck.')return[{kind:'peek',amount:3}];
 if(text==='Look at the top card of your deck. Then, you may shuffle your deck.')return[{kind:'peek',amount:1},{kind:'chooseMode',modes:[{label:'Keep deck order',program:[]},{label:'Shuffle deck',program:[{kind:'shuffleDeck'}]}]}];
 if(text==='Look at the top card of your deck. If that card is a [P] Pokémon, put it into your hand. If it is not a [P] Pokémon, put it on the bottom of your deck.')return[{kind:'peekTopType',category:'Pokemon',type:'P'}];
 if((m=text.match(/^For each of your \[([A-Z])\] Pokémon in play, look at that many cards from the top of (your|your opponent's) deck and put them back in any order\.$/)))return[{kind:'reorder',type:m[1],opponent:m[2]!=="your"}];
 if(text==='Shuffle 2 cards from your hand into your deck. Draw a card. If you can\'t shuffle in 2 cards, you can\'t use this card.')return[{kind:'collect',min:2,max:2,next:[{kind:'shuffleCollected'},{kind:'draw',amount:1}]}];
 if(text==='Flip 3 coins. For each heads, a [W] Pokémon is chosen at random from your discard pile and put into your hand.')return[{kind:'countCoins',count:3,then:{kind:'recoverCoinCards',category:'Pokemon',type:'Water'}}];
 if(text==='Flip a coin until you get tails. For each heads, put a random Pokémon that has “Team Rocket” in its name from your deck into your hand.')return[{kind:'untilTailsSearch',category:'Pokemon',nameContains:'Team Rocket'}];
 if(text==='You can use this card only if your Pokémon in the Active Spot has the Psychic attack. Choose 1 of your opponent\'s Benched Pokémon and move a random Energy from it to your opponent\'s Active Pokémon.')return[{kind:'require',predicate:{test:'activeAttack',name:'Psychic'}},{kind:'choosePokemon',side:'opponent',bench:true,hasEnergy:true,next:[{kind:'moveRandomToActive',opponent:true}]}];
''' +s[i:]
a=s.index('function ability(');i=s.index(' return null;',a);s=s[:i]+r'''
 if(text==='Once during your turn, you may look at the top card of your deck.')return{program:[{kind:'peek',amount:1}]};
 if(text==='Once during your turn, you may look at a random card from your opponent\'s hand.')return{program:[{kind:'peekHand'}]};
 if(text==='You must discard a card from your hand in order to use this Ability. Once during your turn, you may draw a card.')return{program:[{kind:'chooseCard',next:[{kind:'discardChosen'},{kind:'draw',amount:1}]}]};
 if(text==='Once during your turn, you may choose either player. Look at the top card of that player\'s deck.')return{program:[{kind:'chooseMode',modes:[{label:'Your deck',program:[{kind:'peek',amount:1}]},{label:'Opponent deck',program:[{kind:'peek',amount:1,opponent:true}]}]}]};
 if(text==='Once during your turn, if this Pokémon is in the Active Spot, you may look at a random Supporter card from your opponent\'s hand. Use the effect of that card as the effect of this Ability.')return{onlyActive:true,program:[{kind:'copyTrainer',opponent:true,from:'hand'}]};
''' +s[i:];p.write_text(s,encoding='utf-8')
